tool_input.command:
tail -n +2 data/features_train.csv | awk -F, '{
    sum1sq+=($2 - 2.4247)^2;
    sum2sq+=($3 - (-3.26328))^2;
    sum3sq+=($4 - (-0.0300147))^2;
    sum4sq+=($5 - 1.0404)^2;
    count+=1
} END {
    print "f1_std = " sqrt(sum1sq/count);
    print "f2_std = " sqrt(sum2sq/count);
    print "f3_std = " sqrt(sum3sq/count);
    print "f4_std = " sqrt(sum4sq/count);
}'
